args.find:
Raises:
    ValueError: if a non-blank, non-comment line contains no ``=``.
"""
result: dict[str, str] = {}
for raw in text.splitlines():
    line = raw.strip()
    if not line or line.startswith("#"):
        continue
    key, sep, value = line.partition("=")
    if not sep:
        raise ValueError(f"missing '=' in line: {raw!r}")
    result[key.strip()] = value.strip()
return result

args.replace:
A non-blank, non-comment line with no ``=`` is a bare key and parses
as ``""`` (e.g. ``"debug"`` yields ``{"debug": ""}``).
"""
result: dict[str, str] = {}
for raw in text.splitlines():
    line = raw.strip()
    if not line or line.startswith("#"):
        continue
    key, sep, value = line.partition("=")
    if not sep:
        result[key.strip()] = ""
    else:
        result[key.strip()] = value.strip()
return result
